      concepts: [{ id: C.read, category: 'vocabulary', label: 'Lire et écrire', objective: 'Comprendre et employer mamaky pour lire et manoratra pour écrire au présent.', malagasy: 'mamaky · manoratra', french: 'lire · écrire' }],
      reviews: [C.house, C.pronouns, C.question, C.negative, C.now],
